  0 <= D < 2^64 -> 0 <= N < 2^64 ->
  bv_unsigned sp mod 16 = 0 -> aceil <= lo -> lo + 192 + 16 + AFS_STACK <= bv_unsigned sp -> bv_unsigned sp <= 0x7fffffffffff -> tp = Z_to_bv 64 ATP ->
  stk asegs m lo (bv_unsigned sp) -> mem_inv asegs m ->
